import sys
from collections import deque, defaultdict

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build_tree_from_input():
    lines = []
    try:
        while True:
            line = sys.stdin.readline().strip()
            if not line:
                break
            lines.append(line)
    except EOFError:
        pass

    if not lines:
        return None, None, None

    tree_data = {}
    edges = []

    for line in lines:
        parts = line.split()
        if len(parts) < 3:
            continue
        parent_val = int(parts[0])
        left_val = int(parts[1]) if parts[1] != 'null' else None
        right_val = int(parts[2]) if parts[2] != 'null' else None

        if parent_val not in tree_data:
            tree_data[parent_val] = Node(parent_val)
        parent_node = tree_data[parent_val]

        if left_val is not None:
            if left_val not in tree_data:
                tree_data[left_val] = Node(left_val)
            parent_node.left = tree_data[left_val]
            edges.append((parent_val, left_val))

        if right_val is not None:
            if right_val not in tree_data:
                tree_data[right_val] = Node(right_val)
            parent_node.right = tree_data[right_val]
            edges.append((parent_val, right_val))

    root_val = int(lines[0].split()[0])
    root = tree_data.get(root_val)

    home_line = sys.stdin.readline().strip()
    while home_line and not home_line.startswith('home'):
        home_line = sys.stdin.readline().strip()

    home = None
    K = None

    if home_line:
        parts = home_line.replace(' ', '').split(',')
        for p in parts:
            if p.startswith('home'):
                home = int(p.split('=')[1])
            elif p.startswith('K'):
                K = int(p.split('=')[1])

    if home is None:
        home_line = sys.stdin.readline().strip()
        if home_line:
            home = int(home_line)

    if K is None:
        k_line = sys.stdin.readline().strip()
        if k_line:
            K = int(k_line)

    return root, home, K

def find_home_node(root, home):
    if not root:
        return None
    if root.val == home:
        return root

    left_result = find_home_node(root.left, home)
    if left_result:
        return left_result

    return find_home_node(root.right, home)

def build_graph(node, graph, parent=None):
    if not node:
        return
    if parent:
        graph[node.val].append(parent.val)
        graph[parent.val].append(node.val)
    build_graph(node.left, graph, node)
    build_graph(node.right, graph, node)

def ladoos(root, home, K):
    if not root:
        return 0

    graph = defaultdict(list)
    build_graph(root, graph)

    home_node = find_home_node(root, home)
    if not home_node:
        return 0

    visited = set()
    queue = deque([(home, 0)])
    visited.add(home)
    total_ladoos = 0

    while queue:
        current, dist = queue.popleft()
        total_ladoos += current

        if dist >= K:
            continue

        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))

    return total_ladoos

if __name__ == "__main__":
    root, home, K = build_tree_from_input()
    if root and home is not None and K is not None:
        result = ladoos(root, home, K)
        print(result)
    else:
        print(0)
